All linear-in-X variants sit near 0.67; checking with 5-fold CV and a confusion matrix whether some classes are the confusable ones, and whether a length signal matters.
```python
X=np.load("train_x.npy"); y=np.load("train_y.npy"); Bn=(X>0).astype(float)
rng=np.random.RandomState(1); p=rng.permutation(len(y)); folds=np.array_split(p,5)
def nbw(idx,a,F=Bn):
    W=[]
    for c in range(4):
        s=F[idx][y[idx]==c].sum(0)+a; W.append(np.log(s/s.sum()))
    W=np.array(W); return W-W.mean(0)
res={}; conf=np.zeros((4,4),int)
for k in range(5):
    te=folds[k]; tr=np.concatenate([folds[j] for j in range(5) if j!=k])
    for a in [0.3,1,3]:
        W=nbw(tr,a)
        for nm,F in [("Bn",Bn),("X",X),("sqrtX",np.sqrt(X))]:
            pr=(F[te]@W.T).argmax(1); res[(a,nm)]=res.get((a,nm),0)+(pr==y[te]).sum()
            if a==1 and nm=="X":
                for t,q in zip(y[te],pr): conf[t,q]+=1
for k,v in res.items(): print(k, round(v/len(y),3))
print(conf)
L=Bn.sum(1); print("mean nnz per class",[round(L[y==c].mean(),1) for c in range(4)])
