Train 0.818 matches the local check. Testing a few other count-based linear weightings (complement NB, NB on log-counts, NB plus idf centroid average) under the same 5-fold CV to see if any beats 0.706.
```python
X=np.load("train_x.npy"); y=np.load("train_y.npy"); Bn=(X>0).astype(float)
rng=np.random.RandomState(1); p=rng.permutation(len(y)); folds=np.array_split(p,5)
def nb(idx,a,F):
    W=[]
    for c in range(4):
        s=F[idx][y[idx]==c].sum(0)+a; W.append(np.log(s/s.sum()))
    W=np.array(W); return W-W.mean(0)
def cnb(idx,a,F):
    W=[]
    for c in range(4):
        s=F[idx][y[idx]!=c].sum(0)+a; W.append(-np.log(s/s.sum()))
    W=np.array(W); return W-W.mean(0)
def cent(idx,F):
    df=Bn[idx].sum(0); idf=np.log((len(idx)+1)/(df+1))
    T=F*idf; T=T/np.maximum(np.linalg.norm(T,axis=1,keepdims=True),1e-9)
    M=np.array([T[idx][y[idx]==c].mean(0) for c in range(4)])*idf
    return M-M.mean(0)
res={}
for k in range(5):
    te=folds[k]; tr=np.concatenate([folds[j] for j in range(5) if j!=k])
    cands={"nbB1":nb(tr,1,Bn),"nbX1":nb(tr,1,X),"cnbB1":cnb(tr,1,Bn),"cnbB.3":cnb(tr,.3,Bn),"cent":cent(tr,X)}
    Wn=cands["nbB1"]; Wc=cands["cent"]
    for lam in [0.5,1,2]:
        cands[f"mix{lam}"]=Wn/np.abs(Wn).mean()+lam*Wc/np.abs(Wc).mean()
    for nm,W in cands.items():
        res[nm]=res.get(nm,0)+((X[te]@W.T).argmax(1)==y[te]).sum()
for k,v in res.items(): print(k, round(v/len(y),3))
