Complement NB on binary presence reaches 0.727 CV, best so far. Checking its smoothing and a mix with the idf centroid, on two different fold splits to avoid chasing noise.
```python
X=np.load("train_x.npy"); y=np.load("train_y.npy"); Bn=(X>0).astype(float)
def cnb(idx,a,F):
    W=[]
    for c in range(4):
        s=F[idx][y[idx]!=c].sum(0)+a; W.append(-np.log(s/s.sum()))
    W=np.array(W); return W-W.mean(0)
def cent(idx,F):
    df=Bn[idx].sum(0); idf=np.log((len(idx)+1)/(df+1))
    T=F*idf; T=T/np.maximum(np.linalg.norm(T,axis=1,keepdims=True),1e-9)
    M=np.array([T[idx][y[idx]==c].mean(0) for c in range(4)])*idf
    return M-M.mean(0)
res={}
for seed in [1,2]:
    rng=np.random.RandomState(seed); p=rng.permutation(len(y)); folds=np.array_split(p,5)
    for k in range(5):
        te=folds[k]; tr=np.concatenate([folds[j] for j in range(5) if j!=k])
        Wc=cent(tr,X)
        for a in [0.5,1,2,4]:
            Wn=cnb(tr,a,Bn); cands={f"cnb{a}":Wn}
            for lam in [0.5,1]:
                cands[f"cnb{a}+cent{lam}"]=Wn/np.abs(Wn).mean()+lam*Wc/np.abs(Wc).mean()
            for nm,W in cands.items():
                res[nm]=res.get(nm,0)+((X[te]@W.T).argmax(1)==y[te]).sum()
for k,v in res.items(): print(k, round(v/len(y)/2,3))
